// Des: Tests for ru-cana-chec: signature, drift reasons, baseline storage
// Flo: sign fixtures > mutate pages > expect drift reasons > store and reload baseline
// I/O: HTML strings > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const cana = @import("ru-cana-chec.zig"); const fixt = @import("te-fixt-html.zig"); const inde = @import("st-page-inde.zig");
const allo = std.testing.allocator;
test "same page, no drift; tiny text change, no drift" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const one = try cana.sigMake(aren.allocator(), fixt.shop); try std.testing.expect(one.titl and one.ldjs and one.tlen > 20); try std.testing.expect(cana.sigDrif(one, one) == null); const tweak = try cana.sigMake(aren.allocator(), "<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>Blue Widget</title><style>.x{color:red}</style><script>var a = 1;</script><script type=\"application/ld+json\">{\"@type\":\"Product\"}</script></head><body><h1>Blue Widget</h1><p>A fine widget. Ships fast and free A.</p><ul><li>one</li><li>two</li></ul><noscript>enable js</noscript></body></html>"); try std.testing.expect(cana.sigDrif(one, tweak) == null); }
test "lost title, lost JSON-LD, shrunk text and a new layout are all drift" { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const base = try cana.sigMake(aren.allocator(), fixt.shop); const notl = try cana.sigMake(aren.allocator(), "<html><head></head><body><h1>Blue Widget</h1><p>A fine widget. Ships fast and free A.</p><ul><li>one</li><li>two</li></ul></body></html>"); try std.testing.expectEqualStrings("title lost", cana.sigDrif(base, notl).?); const nold = try cana.sigMake(aren.allocator(), "<html><head><title>T</title></head><body><h1>Blue Widget</h1><p>A fine widget. Ships fast and free A.</p></body></html>"); try std.testing.expectEqualStrings("json-ld lost", cana.sigDrif(base, nold).?); const tiny = try cana.sigMake(aren.allocator(), "<html><head><title>T</title><script type=\"application/ld+json\">{}</script></head><body>x</body></html>"); try std.testing.expectEqualStrings("text shrank", cana.sigDrif(base, tiny).?); const spa = try cana.sigMake(aren.allocator(), "<html><head><title>T</title><script type=\"application/ld+json\">{}</script></head><body><div><div><div><span><span><span><span><section><section>Blue Widget A fine widget. Ships fast and free A. one two</section></section></span></span></span></span></div></div></div></body></html>"); try std.testing.expectEqualStrings("dom changed", cana.sigDrif(base, spa).?); }
test "baseline saves and reloads; bad rows skipped" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const sig = try cana.sigMake(aren.allocator(), fixt.shop); try cana.canaSet(&dbzz, aren.allocator(), "http://a/x", sig, 1); try cana.canaSet(&dbzz, aren.allocator(), "http://a/x", sig, 2); try dbzz.exec("INSERT INTO cana VALUES('http://a/bad','not json',1);"); const all = try cana.canaAll(&dbzz, aren.allocator()); try std.testing.expectEqual(@as(usize, 1), all.len); try std.testing.expect(cana.sigDrif(all[0].sig, sig) == null); try std.testing.expectEqual(sig.tlen, all[0].sig.tlen); }
